import argparse
import ast
import hashlib
import sys
from collections.abc import Sequence
from dataclasses import dataclass, field
from pathlib import Path

# copies OrgForge code verbatim from a pinned checkout into src/constellation/_vendor; never edit the output by hand

PREAMBLE = """# Vendored verbatim from aeriesec/orgforge {commit} eval/{source}
# Licence: MIT, see third_party/orgforge/LICENSE.
# Generated by tools/vendor_orgforge.py --profile {profile}; source sha256 {digest}. Do not edit: regenerate.
# ruff: noqa
# mypy: ignore-errors
from __future__ import annotations

import logging
import random
import re
from collections import defaultdict
from dataclasses import asdict, dataclass, field
from pathlib import Path
from statistics import mean
from typing import Any, Dict, List, Optional, Set, Tuple

logger = logging.getLogger("orgforge.vendored")
# upstream duck-types events; any object with SimEvent's attributes is accepted
SimEvent = Any
"""

# the only code not copied: constructors that take events directly instead of a Mongo-backed Memory
INIT = "    def __init__(self, events, mem=None):\n        self._events = events\n        self._mem = mem\n\n"


@dataclass(frozen=True)
class Profile:
    source: str
    out: str
    context: str
    names: tuple[str, ...]
    # classes copied as stub + selected methods, where the constructor needs replacing
    partial: dict[str, tuple[str, ...]] = field(default_factory=dict)
    stubs: dict[str, str] = field(default_factory=dict)


PROFILES = {
    "causal": Profile(
        source="eval_harness.py",
        out="src/constellation/_vendor/orgforge_causal.py",
        context=(
            "# nothing is stripped: generated labels carry unstripped export paths\n"
            'BASE = Path("/__orgforge_export_root__")\n'
            "# the org chart is not needed by any copied decision path; _dept_of_actor sees an empty chart\n"
            'CONFIG = {"org_chart": {}}\n'
        ),
        names=(
            "_ARTIFACT_SUBSYSTEM",
            "_EXPLICIT_CAUSAL_LINKS",
            "_VAGUE_GAP_TERMS",
            "_SILENCE_PAIRS",
            "_RESPONSE_TYPE_SUBSYSTEM",
            "_strip_root",
            "_safe_artifact_values",
            "CausalLink",
            "AbsenceRecord",
        ),
        partial={
            "CausalLinkIndexer": ("_subsystems_for_event", "_find_effect_event", "_counterfactual_template", "build"),
            "AbsenceCatalogBuilder": ("_dept_of_actor", "_match_key", "_expected_search_space", "build"),
        },
        stubs={
            "CausalLinkIndexer": "class CausalLinkIndexer:\n    MAX_LINKS_PER_TYPE: int = 15\n\n",
            "AbsenceCatalogBuilder": "class AbsenceCatalogBuilder:\n",
        },
    ),
    "scoring": Profile(
        source="agentic_eval_harness-v2.py",
        out="src/constellation/_vendor/orgforge_scoring.py",
        context=(
            "# mirrors third_party/orgforge/config.yaml (max_days 60); upstream reads num_days with a default of 60\n"
            'CONFIG = {"simulation": {"max_days": 60, "start_date": "2026-01-01"}}\n'
        ),
        names=(
            "_TRACK_WEIGHTS",
            "ToolCall",
            "AgentTrajectory",
            "PerspectiveTrajectoryScore",
            "CounterfactualTrajectoryScore",
            "SilenceTrajectoryScore",
            "EvalResult",
            "PerspectiveScorer",
            "CounterfactualScorer",
            "SilenceScorer",
        ),
    ),
}


def segment(lines: list[str], node: ast.stmt) -> str:
    # line slice, not get_source_segment: decorators such as @dataclass must survive the copy
    decorators = getattr(node, "decorator_list", [])
    start = min([d.lineno for d in decorators] + [node.lineno]) - 1
    return "".join(lines[start : node.end_lineno]).rstrip("\n")


def _name(node: ast.stmt) -> str | None:
    if isinstance(node, ast.Assign) and isinstance(node.targets[0], ast.Name):
        return node.targets[0].id
    if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
        return node.target.id
    return getattr(node, "name", None)


def extract(source: str, profile: Profile) -> str:
    lines = source.splitlines(keepends=True)
    tree = ast.parse(source)
    missing = set(profile.names) - {_name(n) for n in tree.body}
    if missing:
        raise SystemExit(f"names not found upstream: {sorted(missing)}")
    out: list[str] = []
    for node in tree.body:
        if _name(node) in profile.names:
            out.append(segment(lines, node))
        if isinstance(node, ast.ClassDef) and node.name in profile.partial:
            copied = profile.partial[node.name]
            body = [segment(lines, m) for m in node.body if isinstance(m, ast.FunctionDef) and m.name in copied]
            out.append(profile.stubs[node.name] + INIT + "\n\n".join(body))
    return "\n\n\n".join(out) + "\n"


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("eval_dir", type=Path, help="orgforge/eval at the pinned commit")
    parser.add_argument("--commit", required=True)
    parser.add_argument("--profile", choices=sorted(PROFILES), required=True)
    args = parser.parse_args(argv)
    profile = PROFILES[args.profile]
    text = (args.eval_dir / profile.source).read_text()
    digest = hashlib.sha256(text.encode()).hexdigest()
    head = PREAMBLE.format(commit=args.commit, source=profile.source, profile=args.profile, digest=digest)
    Path(profile.out).write_text(head + profile.context + "\n\n" + extract(text, profile))
    print(f"wrote {profile.out} from {profile.source} sha256 {digest[:12]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
